             implies inner@.free_frames.contains(addr) by {
             let x = choose|x: int| clear.contains(x) && addr == f(x);
             assert(0 <= x < n && !sb.contains(x));
         }
     }
     lemma_map_size(clear, inner@.free_frames, f);
 }

